import { expect, test } from "bun:test";
import { slugify } from "./slugify.ts";
test("accents", () => expect(slugify("Crème Brûlée")).toBe("creme-brulee"));
test("case", () => expect(slugify("HELLO")).toBe("hello"));
test("punctuation runs", () => expect(slugify("a -- b!!c")).toBe("a-b-c"));
test("trim separators", () => expect(slugify("  -hi-  ")).toBe("hi"));
test("digits", () => expect(slugify("Top 10 Tips")).toBe("top-10-tips"));
test("empty", () => expect(slugify("")).toBe(""));
